+                a0[0] + (a1[0] - a0[0]) * t,
+                a0[1] + (a1[1] - a0[1]) * t,
+                a0[2] + (a1[2] - a0[2]) * t,
+            ];
+            let l = (ax[0] * ax[0] + ax[1] * ax[1] + ax[2] * ax[2]).sqrt();
